-- Synthetic catalog fixture. Run only in the dedicated schemacraft_fixture test database.
DROP SCHEMA IF EXISTS "odd.schema" CASCADE;
DROP SCHEMA IF EXISTS sales CASCADE;
DROP SCHEMA IF EXISTS automation CASCADE;
CREATE SCHEMA sales;
CREATE SCHEMA automation;
CREATE SCHEMA "odd.schema";
CREATE TYPE sales.order_state AS ENUM ('draft','confirmed','cancelled');
CREATE DOMAIN sales.currency_code AS character(3) CHECK (VALUE ~ '^[A-Z]{3}$');
CREATE SEQUENCE sales.customer_ticket_seq;

CREATE TABLE sales.customers (
    customer_id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    ticket_number bigint NOT NULL DEFAULT nextval('sales.customer_ticket_seq'::regclass),
    parent_id integer REFERENCES sales.customers(customer_id),
    display_name text NOT NULL,
    external_code text UNIQUE NULLS NOT DISTINCT,
    currency sales.currency_code NOT NULL DEFAULT 'USD',
    tags text[] NOT NULL DEFAULT ARRAY[]::text[],
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb
);
CREATE TABLE sales.orders (
    order_id uuid PRIMARY KEY,
    customer_id integer NOT NULL,
    state sales.order_state NOT NULL DEFAULT 'draft',
    created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    large_amount numeric(1000,-3),
    total numeric(18,2) NOT NULL DEFAULT 0 CHECK (total>=0),
    doubled_total numeric GENERATED ALWAYS AS (total*2) STORED,
    CONSTRAINT fk_order_customer FOREIGN KEY(customer_id) REFERENCES sales.customers(customer_id)
        ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE sales.order_lines (
    order_id uuid NOT NULL REFERENCES sales.orders(order_id) ON DELETE CASCADE,
    line_no integer NOT NULL,
    product text NOT NULL,
    quantity integer NOT NULL DEFAULT 1 CHECK(quantity>0),
    PRIMARY KEY(order_id,line_no)
);
CREATE TABLE sales.composite_parent (
    tenant_id integer NOT NULL, code integer NOT NULL, PRIMARY KEY(tenant_id,code)
);
CREATE TABLE sales.composite_child (
    tenant_id integer, code integer, description text,
    CONSTRAINT fk_full FOREIGN KEY(tenant_id,code) REFERENCES sales.composite_parent(tenant_id,code)
        MATCH FULL ON DELETE NO ACTION DEFERRABLE
);
CREATE TABLE sales.subset_child (
    tenant_id integer NOT NULL, code integer,
    CONSTRAINT fk_subset FOREIGN KEY(tenant_id,code) REFERENCES sales.composite_parent(tenant_id,code)
        ON DELETE SET NULL(code)
);
CREATE TABLE sales.events (
    happened_on date NOT NULL, event_id bigint GENERATED BY DEFAULT AS IDENTITY, payload jsonb,
    PRIMARY KEY(happened_on,event_id)
) PARTITION BY RANGE(happened_on);
CREATE TABLE sales.events_2026 PARTITION OF sales.events FOR VALUES FROM ('2026-01-01') TO ('2027-01-01');
CREATE TABLE "odd.schema"."order.items" (
    "Id" integer PRIMARY KEY, "line.total" numeric(10,2), "cost]net" text,
    customer_id integer CONSTRAINT fk_cross_schema REFERENCES sales.customers(customer_id)
);
CREATE UNIQUE INDEX ux_customers_lower_name ON sales.customers(lower(display_name)) WHERE parent_id IS NULL;
CREATE FUNCTION sales.normalized_name(text) RETURNS text LANGUAGE SQL IMMUTABLE
AS 'SELECT pg_catalog.lower($1)';
CREATE FUNCTION sales.has_nonempty_name(text) RETURNS boolean LANGUAGE SQL IMMUTABLE
AS 'SELECT pg_catalog.length($1)>0';
CREATE INDEX ix_customers_normalized_name ON sales.customers(sales.normalized_name(display_name))
WHERE sales.has_nonempty_name(display_name);
CREATE INDEX ix_orders_customer ON sales.orders(customer_id) INCLUDE(total) WHERE total>0;
CREATE INDEX ix_customer_metadata ON sales.customers USING gin(metadata);
ALTER TABLE sales.orders ADD CONSTRAINT ck_optional_amount CHECK(large_amount IS NULL OR large_amount>=0) NOT VALID;

CREATE VIEW sales.order_summary AS
SELECT o.order_id,c.display_name,o.total FROM sales.orders o JOIN sales.customers c USING(customer_id);
CREATE VIEW sales.active_customers AS SELECT * FROM sales.customers WHERE parent_id IS NULL WITH LOCAL CHECK OPTION;
CREATE MATERIALIZED VIEW sales.customer_totals AS
SELECT customer_id,sum(total) AS total FROM sales.orders GROUP BY customer_id WITH NO DATA;

CREATE FUNCTION sales.order_total(integer) RETURNS numeric LANGUAGE SQL
BEGIN ATOMIC
    SELECT COALESCE(sum(total),0) FROM sales.orders WHERE customer_id=$1;
END;
CREATE FUNCTION sales.order_total(uuid) RETURNS numeric LANGUAGE SQL AS $body$
    SELECT total FROM sales.orders WHERE order_id=$1
$body$;
CREATE FUNCTION sales.customer_orders(integer) RETURNS TABLE(order_id uuid,total numeric)
LANGUAGE SQL AS $body$ SELECT order_id,total FROM sales.orders WHERE customer_id=$1 $body$;
CREATE FUNCTION sales.scalar_series(integer) RETURNS SETOF integer LANGUAGE SQL
AS $body$ SELECT pg_catalog.generate_series(1,$1) $body$;
CREATE FUNCTION automation.label(integer) RETURNS text LANGUAGE SQL AS 'SELECT $1::text';
CREATE PROCEDURE sales.confirm_order(IN selected_order uuid, INOUT changed integer DEFAULT 0)
LANGUAGE plpgsql AS $body$
BEGIN
    UPDATE sales.orders SET state='confirmed' WHERE order_id=selected_order;
    GET DIAGNOSTICS changed = ROW_COUNT;
END;
$body$;
CREATE FUNCTION sales.touch_order() RETURNS trigger LANGUAGE plpgsql AS $body$
BEGIN NEW.created_at=CURRENT_TIMESTAMP; RETURN NEW; END;
$body$;
CREATE FUNCTION sales.audit_statement() RETURNS trigger LANGUAGE plpgsql AS $body$
BEGIN RETURN NULL; END;
$body$;
CREATE FUNCTION sales.edit_active_customer() RETURNS trigger LANGUAGE plpgsql AS $body$
BEGIN UPDATE sales.customers SET display_name=NEW.display_name WHERE customer_id=OLD.customer_id; RETURN NEW; END;
$body$;
CREATE TRIGGER before_order BEFORE INSERT OR UPDATE OF total ON sales.orders
FOR EACH ROW EXECUTE FUNCTION sales.touch_order();
CREATE TRIGGER after_order AFTER DELETE ON sales.orders
FOR EACH STATEMENT EXECUTE FUNCTION sales.audit_statement();
ALTER TABLE sales.orders DISABLE TRIGGER after_order;
CREATE TRIGGER replica_order AFTER INSERT ON sales.orders
FOR EACH STATEMENT EXECUTE FUNCTION sales.audit_statement();
ALTER TABLE sales.orders ENABLE REPLICA TRIGGER replica_order;
CREATE TRIGGER truncate_orders AFTER TRUNCATE ON sales.orders
FOR EACH STATEMENT EXECUTE FUNCTION sales.audit_statement();
CREATE TRIGGER edit_customer INSTEAD OF UPDATE ON sales.active_customers
FOR EACH ROW EXECUTE FUNCTION sales.edit_active_customer();
CREATE CONSTRAINT TRIGGER deferred_order AFTER INSERT ON sales.orders DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION sales.audit_statement();

INSERT INTO sales.customers(display_name,external_code) VALUES('Synthetic Customer','DEMO-1');
INSERT INTO sales.orders(order_id,customer_id,total) VALUES('00000000-0000-0000-0000-000000000001',1,100);

DO $fixture$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname='schemacraft_pg_reader') THEN
        CREATE ROLE schemacraft_pg_reader LOGIN PASSWORD 'SchemaCraftPgReader!2026';
    END IF;
END;
$fixture$;
REVOKE ALL ON SCHEMA sales,automation,"odd.schema" FROM schemacraft_pg_reader;
GRANT CONNECT ON DATABASE schemacraft_fixture TO schemacraft_pg_reader;
